// Every question from the seven graded quizzes, sorted into study-guide chapters.
// Fields:
//   id, ch (chapter id), src (quiz + question number), type (mc | tf | match | essay)
//   mc/tf: q, options[], answer (index of correct option), explain
//   match: q, pairs [{p: prompt, a: correct answer}], explain
//   essay: q, model (example of a full-credit answer), explain
//   missed: true when you lost points on the quiz; you = what you answered
//   figure: text description of an image that was part of the question
// All content is plain ASCII.

window.QUESTIONS = [

// ---------------- Chapter 2 Quiz: Introduction to Environmental Concepts (19/21) ----------------
{ id:"c2-1", ch:"ch1_2", src:"Ch 2 quiz Q1", type:"mc",
  q:"Which of the following is likely to cause environmental problems?",
  options:["rapid population growth","a more even distribution of wealth","increasingly sustainable use of resources","'meeting the needs of the present without compromising the ability of future generations to meet their own needs'"],
  answer:0, explain:"Population growth drives consumption, habitat loss, and pollution. The other three are solutions (the last is the definition of sustainable development)." },
{ id:"c2-2", ch:"ch1_2", src:"Ch 2 quiz Q2", type:"mc",
  q:"One way to decrease the size of our ecological footprint is to",
  options:["Decrease consumption rates","Increase consumption rates","Increase the development in the region","Reduce the size of a biologically productive area in the region","None of these, it is not possible to change the size of an ecological footprint"],
  answer:0, explain:"Footprint = land and water needed to supply what you consume and absorb your waste, so consuming less shrinks it." },
{ id:"c2-3", ch:"ch1_2", src:"Ch 2 quiz Q3", type:"mc",
  q:"What makes up an ecosystem?",
  options:["Living and nonliving parts and the processes that disconnect them","Living and nonliving parts and the processes that connect them","Living and nonliving parts and energy movement created by the sun","Energy and matter and the organisms functioning apart","Energy and matter and the organisms competing for resources in the ecosystem"],
  answer:1, explain:"An ecosystem is biotic plus abiotic components plus the energy flows and nutrient cycles that connect them." },
{ id:"c2-4", ch:"ch1_2", src:"Ch 2 quiz Q4", type:"mc",
  q:"Which of the following statements best describes the philosophy of utilitarian conservation?",
  options:["'Resources should be used for the greatest good, for the greatest number, for the longest time'","'Forests should be saved for their aesthetic value alone, because they provide shelter for the wild creatures of the wilderness'","'Resources should be saved for use in the future'","'Natural resources are totally expendable, and should not be saved, rather, used to the fullest extent of the law'"],
  answer:0, explain:"Gifford Pinchot's wise-use philosophy. Option B is biocentric preservation (Muir)." },
{ id:"c2-5", ch:"ch1_2", src:"Ch 2 quiz Q5", type:"mc",
  q:"The National Park Service reflects a ________ approach while the Forest Service reflects a ________ approach.",
  options:["Biocentric preservationist; pragmatic utilitarian conservationist","Global environmentalist; cornucopian","Pragmatic resource conservationist; moral and aesthetic preservationist","Cornucopian; global environmentalist","Pragmatic utilitarian conservation; biocentric preservation"],
  answer:0, explain:"Parks preserve (Muir); national forests are managed for use (Pinchot). Option E has them reversed." },
{ id:"c2-6", ch:"ch1_2", src:"Ch 2 quiz Q6", type:"mc",
  q:"The fundamental basis of environmental science as a discipline is the",
  options:["History of the use of natural resources","Diversity of life on Earth","Human impact on the Earth","Pollution on the Earth","Future use of natural resources"],
  answer:2, explain:"Environmental science centers on how humans affect the planet and how to fix it." },
{ id:"c2-7", ch:"ch1_2", src:"Ch 2 quiz Q7", type:"mc",
  q:"Supplies of fossil fuels are",
  options:["Continually expanding in nature","Being renewed as fast as we use them","Being steadily depleted","Almost entirely depleted","Easily found through better technology"],
  answer:2, explain:"Fossil fuels are nonrenewable on a human time scale; they are declining but not yet nearly gone." },
{ id:"c2-8", ch:"ch1_2", src:"Ch 2 quiz Q8", type:"mc",
  q:"Which of the following best describes the concept of 'sustainable development'?",
  options:["'meeting the needs of the present without compromising the ability of future generations to meet their own needs'","'to each according to his need, from each according to his ability'","'a stationary condition of capital and population growth'"],
  answer:0, explain:"The Brundtland Commission definition." },
{ id:"c2-9", ch:"ch1_2", src:"Ch 2 quiz Q9", type:"mc", missed:true, you:3,
  q:"Global population is projected to be about ________ in 2050.",
  options:["7 billion","8 billion","9 billion","10 billion","11 billion"],
  answer:2, explain:"You answered 10 billion. The textbook projection is about 9 billion by 2050 (current population is about 8 billion)." },
{ id:"c2-10", ch:"ch1_2", src:"Ch 2 quiz Q10", type:"mc",
  q:"Environmental science is a __________.",
  options:["Narrowly defined set of physical, life and social sciences","Theoretical approach in interpreting the environment","Way to see the world in scientific terms","Systematic approach in learning about the environment","Special set of problem-solving skills"],
  answer:3, explain:"It is systematic and interdisciplinary, not narrow or purely theoretical." },
{ id:"c2-11", ch:"ch1_2", src:"Ch 2 quiz Q11", type:"mc",
  q:"Which U.S. president established the framework of our national forest, park, and wildlife refuge systems?",
  options:["Theodore Roosevelt","John Muir","Franklin Roosevelt","Dwight Eisenhower"],
  answer:0, explain:"Teddy Roosevelt, working with Gifford Pinchot, protected about 230 million acres." },
{ id:"c2-12", ch:"ch1_2", src:"Ch 2 quiz Q12", type:"mc",
  q:"4/5 of the world's population lives in countries where nearly everyone is poor by North American standards. Most of those countries are in:",
  options:["Africa","North America","Latin America","Asia"],
  answer:3, explain:"Asia holds the largest share of the world's population, including China, India, and most of the low-income population." },
{ id:"c2-13", ch:"ch1_2", src:"Ch 2 quiz Q13", type:"mc",
  q:"The term 'toxic colonialism' has been used in describing",
  options:["Lax environmental regulations for toxic wastes","The exportation of toxic wastes to poor communities","Rulings that toxins must not be exported to wealthy nations","The high level of toxic waste production by wealthy nations","The high level of toxic pesticide use by wealthy nations"],
  answer:1, explain:"Rich nations and companies dump hazardous waste on poor communities and countries." },
{ id:"c2-14", ch:"ch1_2", src:"Ch 2 quiz Q14", type:"mc",
  q:"Which of the following environmental philosophies emphasizes the fundamental rights of other organisms to exist and pursue their own interests?",
  options:["utilitarian conservation","global environmentalism","environmentalism","biocentric preservation"],
  answer:3, explain:"Biocentric = life-centered; nature has inherent value." },
{ id:"c2-15", ch:"ch1_2", src:"Ch 2 quiz Q15", type:"mc",
  q:"The Hetch Hetchy Valley court case is important environmental history because it was a case that argued for the",
  options:["Inherent value of trees, rocks and wildlife","Instrumental value of trees, rocks and wildlife","Status of moral agents for trees, rocks and wildlife","Sustainable development of the area","Moral consideration of sentient things"],
  answer:0, explain:"Muir argued the valley had worth in itself, not just as a reservoir site." },
{ id:"c2-16", ch:"ch1_2", src:"Ch 2 quiz Q16", type:"mc",
  q:"Proponents of sustainable development argue that",
  options:["All development has environmental costs","Development is less important than the environment","Development can proceed with minimal costs to the environment","The environment is less important than development","Development does not cause environmental damage"],
  answer:2, explain:"Sustainable development tries to balance economic growth with environmental protection." },
{ id:"c2-17", ch:"ch1_2", src:"Ch 2 quiz Q17", type:"mc", missed:true, you:3,
  q:"What publication is considered to have awakened the public to the threats of pollution and toxic chemicals, beginning the 'environmentalism' movement?",
  options:["Our Environment by Theodore Roosevelt","Man and Nature by George Perkins","Silent Spring by Rachel Carson","Stuart Little by E. B. White"],
  answer:2, explain:"You answered Stuart Little. Rachel Carson's Silent Spring (1962) on DDT launched modern environmentalism. (Man and Nature by George Perkins Marsh, 1864, was an early conservation text.)" },
{ id:"c2-18", ch:"ch1_2", src:"Ch 2 quiz Q18", type:"mc",
  q:"The branch of philosophy concerned with the distinction between right and wrong and the ultimate worth of actions or things is",
  options:["Values","Ethics","Morals","Attitudes","Characters"],
  answer:1, explain:"Ethics is the formal study; morals and values are what ethics examines." },
{ id:"c2-19", ch:"ch1_2", src:"Ch 2 quiz Q19", type:"mc",
  q:"Sustainable use of resources requires ________.",
  options:["knowledge of all non-renewable resources","knowledge of all finite resource locations","an understanding of ecosystem models","an understanding of rate of resource renewal and ability to manage rate of use","a thorough understanding of the scientific method"],
  answer:3, explain:"Sustainability means use rate does not exceed renewal rate." },
{ id:"c2-20", ch:"ch1_2", src:"Ch 2 quiz Q20", type:"mc",
  q:"Sustainable development, ideally, improves living conditions",
  options:["For a few decades into the future","For the entire current political administration","As long as resources last","For generations in the future","For the present generation"],
  answer:3, explain:"The definition explicitly protects future generations." },
{ id:"c2-21", ch:"ch1_2", src:"Ch 2 quiz Q21", type:"mc",
  q:"If everybody in the world used resources at the rate that people in the United States do,",
  options:["People would be healthier and happier worldwide","Our current resources would run out quickly","Violent conflicts would decrease because basic needs would be met"],
  answer:1, explain:"The US footprint would require several Earths if everyone shared it." },

// ---------------- Quiz - Science, Ch 3 (20/21) ----------------
{ id:"c3-1", ch:"ch3", src:"Ch 3 quiz Q1", type:"mc",
  q:"Proof in science is always",
  options:["Firmly established","Beyond question","An impossible goal","Changing very quickly","Open to question or new evidence"],
  answer:4, explain:"Science is tentative; nothing is proven beyond revision." },
{ id:"c3-2", ch:"ch3", src:"Ch 3 quiz Q2", type:"mc",
  q:"Double-blind studies are especially useful in",
  options:["Genetic experiments","Health studies","Statistical analysis","Opinion surveys","Double-blind studies are not useful in any situation"],
  answer:1, explain:"They remove the placebo effect and researcher expectation bias in drug and medical trials." },
{ id:"c3-3", ch:"ch3", src:"Ch 3 quiz Q3", type:"mc",
  q:"Which of the following is NOT a property of modern science?",
  options:["Results are repeatable","Explanations are falsifiable.","Theories are dogmatic.","Conclusions must be defended through peer review.","All conclusions possess an element of uncertainty."],
  answer:2, explain:"Dogmatic means held regardless of evidence; science is the opposite." },
{ id:"c3-4", ch:"ch3", src:"Ch 3 quiz Q4", type:"mc",
  q:"___________ allow scientists to gather information about complicated and interrelated environmental systems.",
  options:["Charts","Graphs","Models","Figures","Paradigm shifts"],
  answer:2, explain:"Models simplify systems too big or slow to experiment on directly." },
{ id:"c3-5", ch:"ch3", src:"Ch 3 quiz Q5", type:"mc",
  q:"Generally, distinguished scientists",
  options:["Always agree if they really are expert scientists","May have different interpretations of the same evidence","Never disagree once a theory is established","Believe each other and support each other in their work","Always disagree so they can prove theories"],
  answer:1, explain:"Disagreement over interpretation is normal and healthy in science." },
{ id:"c3-6", ch:"ch3", src:"Ch 3 quiz Q6", type:"mc", missed:true, you:0,
  q:"Which of the following is most significantly absent from the sequence of the scientific method listed here? 'Formulate a hypothesis, then design and perform an experiment, evaluate results and then draw a conclusion. Formulate a theory from this conclusion.'",
  options:["Peer Review","Repetition","Deduction","Statistical analysis"],
  answer:1, explain:"You answered Peer Review. The sequence jumps from one experiment straight to a theory; a theory requires the result to be repeated (replicated) many times. Repetition is the missing step; peer review comes at publication but is not what makes a single result into a theory." },
{ id:"c3-7", ch:"ch3", src:"Ch 3 quiz Q7", type:"match",
  q:"Match the activity to the form of anti-intellectualism it conveys.",
  pairs:[
    { p:"At a political rally a candidate mocks scientists as biased and disconnected with the problems of real people.", a:"Anti-elitism" },
    { p:"TV ratings show that singing competitions rate much higher than science documentaries.", a:"Hedonism" },
    { p:"Shifting of federal grant evaluation toward favoring applied research beneficial to business.", a:"Instrumentalism" },
    { p:"Expressing fear that education has caused the decline in church attendance.", a:"Anti-rationalism" }
  ],
  extra:["Postmodernism"],
  explain:"Anti-elitism = distrust of experts; hedonism = entertainment over learning; instrumentalism = knowledge only for payoff; anti-rationalism = faith over reason; postmodernism (not used here) = all truth is relative." },
{ id:"c3-8", ch:"ch3", src:"Ch 3 quiz Q8", type:"match",
  q:"Match the description to the most appropriate scientific term.",
  pairs:[
    { p:"The assumption that the laws of nature remain unchanged from the present form, throughout time and space", a:"Uniformitarianism" },
    { p:"Results not typical of the norm or taken out of context", a:"Anecdotal" },
    { p:"An assumption of science that all things are explainable through natural forces", a:"Natural causality" },
    { p:"The condition where a theory is supported by observations from many disciplines", a:"Consilience" },
    { p:"The process by which modern science sorts out rigorous studies from poorly designed studies during the publication process", a:"Peer review" },
    { p:"Dogmatic", a:"Characterized as any belief that is considered true regardless of whether it really is" }
  ],
  explain:"These five assumptions and processes are the backbone of the Ch 3 vocabulary." },
{ id:"c3-9", ch:"ch3", src:"Ch 3 quiz Q9", type:"mc",
  q:"In an experimental procedure, the _______________ is manipulated by the investigator to determine whether it influences the phenomenon of interest.",
  options:["standardized variable","control group","dependent variable","independent variable","Both control group and standardized variable are correct."],
  answer:3, explain:"Independent = what you change; dependent = what you measure." },
{ id:"c3-10", ch:"ch3", src:"Ch 3 quiz Q10", type:"mc",
  q:"'I've gotten the same result over and over again!' This statement best demonstrates",
  options:["reliability.","validity.","the placebo effect.","All of these statements are true."],
  answer:0, explain:"Reliability is repeatability. Validity would be whether the measurement means what you think it means." },
{ id:"c3-11", ch:"ch3", src:"Ch 3 quiz Q11", type:"mc",
  q:"Random samples are used",
  options:["to eliminate bias from a study.","Only when large samples are not available.","To eliminate the need for a rigorous method of choice.","Only in double-blind medical experiments."],
  answer:0, explain:"Random selection prevents the researcher from (even unconsciously) choosing favorable subjects." },
{ id:"c3-12", ch:"ch3", src:"Ch 3 quiz Q12", type:"mc",
  q:"Which of the following statements is MOST correct?",
  options:["Science is always right.","Nonscientific study has little value.","Science has all the answers.","Science seeks to explain natural occurrences."],
  answer:3, explain:"Science is a method for explaining nature, not a claim to infallibility or completeness." },
{ id:"c3-13", ch:"ch3", src:"Ch 3 quiz Q13", type:"mc",
  figure:"Flow diagram: Theory -(A)-> Prediction; Observation -(B)-> Prediction; Observation -(C)-> Theory.",
  q:"Examine the flow diagram. Which form of reasoning would occur at step C (Observation -> Theory)?",
  options:["Inductive","Deductive","Reductive","Hypothetical","Empirical"],
  answer:0, explain:"Specific observations to a general theory is induction. Theory to prediction (A) is deduction." },
{ id:"c3-14", ch:"ch3", src:"Ch 3 quiz Q14", type:"mc",
  q:"A control group differs from an experimental group",
  options:["in the number of test organisms used.","by the independent variable.","in several ways.","in no way."],
  answer:1, explain:"Everything is identical except the one factor being tested." },
{ id:"c3-15", ch:"ch3", src:"Ch 3 quiz Q15", type:"mc",
  q:"Art, theology, and philosophy are nonsciences because they",
  options:["are not worthwhile fields of study.","are basically untrue.","deal with things that cannot be tested by the scientific method.","are bodies of knowledge too small to qualify as science."],
  answer:2, explain:"Nonscience is not a judgment of worth; it means the claims are not empirically testable." },
{ id:"c3-16", ch:"ch3", src:"Ch 3 quiz Q16", type:"mc",
  q:"When using the scientific method, scientists make several fundamental assumptions. Which of these does not make sense, based on your knowledge of the scientific method?",
  options:["There are specific causes for events observed in the natural world.","The causes for events can be identified.","There are general rules or patterns that can be used to describe what happens in nature.","An event that occurs repeatedly probably has different causes."],
  answer:3, explain:"Uniformitarianism and natural causality imply repeated events share the same cause." },
{ id:"c3-17", ch:"ch3", src:"Ch 3 quiz Q17", type:"mc",
  q:"Which one of the following BEST distinguishes scientific areas of study from those that are not science?",
  options:["Nonscientific areas of study have few facts.","Scientific areas of study publish their findings and ideas.","Scientific areas of study rarely make mistakes.","Scientific areas of study always test their assumptions and ideas."],
  answer:3, explain:"Testing (and the possibility of being wrong) is the defining feature." },
{ id:"c3-18", ch:"ch3", src:"Ch 3 quiz Q18 (answer cut off in PDF)", type:"mc",
  q:"Which is a correct sequence of steps in the scientific method?",
  options:["Observation, question, hypothesis, prediction, experiment/test, analysis, conclusion (then replicate and publish)","Theory, hypothesis, observation, conclusion, experiment","Conclusion, hypothesis, experiment, observation, theory","Hypothesis, theory, experiment, observation, conclusion"],
  answer:0, explain:"The PDF cut off the options for this question; the standard order is observe -> question -> hypothesize -> predict -> test -> analyze -> conclude, then replicate and peer review." },

// ---------------- Chap 4+ and Life in Balance Quiz (21/21) ----------------
{ id:"c4-1", ch:"ch4", src:"Ch 4 quiz Q1", type:"mc",
  q:"Which of the following best describes matter?",
  options:["everything that takes up space and has mass","a group of atoms that exist as a single unit","sharing electrons","all of the above"],
  answer:0, explain:"Definition of matter. B describes a molecule and C a covalent bond." },
{ id:"c4-2", ch:"ch4", src:"Ch 4 quiz Q2", type:"mc",
  q:"Living vegetation and the ocean are known as 'carbon sinks' because",
  options:["They are made of carbon","They create carbon","They destroy carbon","They store carbon","Due to gravity carbon is found closer to the ground"],
  answer:3, explain:"A sink is a reservoir that takes up and holds carbon." },
{ id:"c4-3", ch:"ch4", src:"Ch 4 quiz Q3", type:"mc",
  q:"Which of the following is not a step in the global nitrogen cycle?",
  options:["Nitrogen fixation","Nitrification","Photosynthesis","Ammonification","Denitrification"],
  answer:2, explain:"Photosynthesis belongs to the carbon cycle." },
{ id:"c4-4", ch:"ch4", src:"Ch 4 quiz Q4", type:"mc",
  q:"If an ecosystem exchanges both matter and energy with its surroundings, it would be referred to as a(n) ______ system.",
  options:["Closed","Open","Dynamic","Isolated","Interactive"],
  answer:1, explain:"Open = matter and energy; closed = energy only; isolated = neither." },
{ id:"c4-5", ch:"ch4", src:"Ch 4 quiz Q5", type:"mc",
  q:"Potential energy is _______ energy.",
  options:["Electrical","Motion","Stored","Heat","Latent"],
  answer:2, explain:"Potential = stored; kinetic = motion." },
{ id:"c4-6", ch:"ch4", src:"Ch 4 quiz Q6", type:"match",
  q:"Match the term to the appropriate description.",
  pairs:[
    { p:"Primary Producer", a:"Typically photosynthetic organisms." },
    { p:"Omnivore", a:"Can occupy space at any level of consumers." },
    { p:"Primary Consumer", a:"Herbivores" },
    { p:"Tertiary Consumer", a:"Predators that lie at the top of the food chain." }
  ],
  explain:"Trophic level vocabulary." },
{ id:"c4-7", ch:"ch4", src:"Ch 4 quiz Q7", type:"mc",
  figure:"Grassland energy diagram: sun -> 1st trophic level (grass, primary producers) -> 2nd (snail, primary consumer) -> 3rd (thrush, secondary consumer) -> 4th (fox, tertiary consumer); decomposers (mushrooms) receive from all levels.",
  q:"In this grassland ecosystem, where is the most chemical energy located?",
  options:["Decomposers","1st trophic level","2nd trophic level","3rd trophic level","4th trophic level"],
  answer:1, explain:"Producers hold the most energy; about 90 percent is lost at each step up." },
{ id:"c4-8", ch:"ch4", src:"Ch 4 quiz Q8", type:"mc",
  q:"Energy is the ability to",
  options:["Move objects","Become heated","Transfer heat from one object to another","Move objects and become heated","Move objects and transfer heat from one object to another"],
  answer:4, explain:"Energy = capacity to do work (move things) or transfer heat." },
{ id:"c4-9", ch:"ch4", src:"Ch 4 quiz Q9", type:"mc",
  q:"Given what you know about the laws of thermodynamics, which of the following animals is the most efficient in its use of energy? Hint: consider body heat loss.",
  options:["Human","Bird","Salamander","Mouse"],
  answer:2, explain:"Only the salamander is cold-blooded, so it does not waste energy generating body heat." },
{ id:"c4-10", ch:"ch4", src:"Ch 4 quiz Q10", type:"mc",
  q:"Nitrogen is an essential component of",
  options:["Amino acids and proteins","Organic molecules","Sugars, the product of photosynthesis","The hydrologic cycle","Carbohydrates"],
  answer:0, explain:"Every amino acid contains nitrogen; sugars and carbohydrates do not." },
{ id:"c4-11", ch:"ch4", src:"Ch 4 quiz Q11", type:"mc",
  q:"The second law of thermodynamics states that as energy moves through different forms and systems it gradually",
  options:["Becomes more concentrated","Dissipates and becomes unavailable","Disappears and is lost","Accumulates in the form of electricity","Changes from kinetic to potential energy"],
  answer:1, explain:"Energy is not lost (1st law) but it degrades to useless heat (2nd law)." },
{ id:"c4-12", ch:"ch4", src:"Ch 4 quiz Q12", type:"mc",
  q:"The first law of thermodynamics and the law of conservation of matter are similar in that",
  options:["Under normal circumstances neither energy nor matter is created nor destroyed","Both energy and matter are recycled through biological systems","Both energy and matter flow in a one-way path through biological systems","Under normal circumstances energy and matter are destroyed as they pass through biological systems","The first law of thermodynamics and the law of conservation of matter are not similar"],
  answer:0, explain:"Both are conservation laws. Note that matter cycles but energy flows one way, so B and C are wrong." },
{ id:"c4-13", ch:"ch4", src:"Ch 4 quiz Q13", type:"mc",
  q:"Which of the following is a form of energy?",
  options:["Electricity","Food","Heat","Light","All of these are forms of energy"],
  answer:4, explain:"Food holds chemical potential energy; the rest are kinetic forms." },
{ id:"c4-14", ch:"lib", src:"Ch 4 quiz Q14", type:"mc",
  q:"According to Niles in 'Life in the Balance', the development of what in human history effectively declared war on the local ecosystems, by freeing us from natural population regulation?",
  options:["Development of Agriculture","Medical revolution","Invention of the car","The introduction of the shopping mall"],
  answer:0, explain:"Instructor feedback: 'as you will see, medicine was a key factor too,' but agriculture came first." },
{ id:"c4-15", ch:"lib", src:"Ch 4 quiz Q15", type:"tf",
  q:"The majority of our atmospheric oxygen comes from tropical rainforests.",
  options:["True","False"], answer:1,
  explain:"Marine photosynthetic microbes (phytoplankton) produce the majority of Earth's oxygen." },
{ id:"c4-16", ch:"lib", src:"Ch 4 quiz Q16", type:"tf",
  q:"Increasing the concentration of oxygen in the atmosphere would benefit most life on this planet.",
  options:["True","False"], answer:1,
  explain:"Fires would burn out of control if oxygen were higher." },
{ id:"c4-17", ch:"lib", src:"Ch 4 quiz Q17", type:"mc",
  q:"According to an estimate by E.O. Wilson, about how many species are we losing to extinction each hour?",
  options:["27,000","100","3","1"],
  answer:2, explain:"About 3 per hour (roughly 27,000 per year), thousands of times faster than new species evolve." },
{ id:"c4-18", ch:"lib", src:"Ch 4 quiz Q18", type:"mc",
  q:"According to the article 'Life in the Balance', why are tropical species more vulnerable to extinction than higher latitude species?",
  options:["Tropical species require a narrower set of conditions to survive.","Tropical species have restricted ranges where they are found","There is greater competition for survival in the diverse tropics","All the above"],
  answer:3, explain:"Narrow tolerances, small ranges, and intense competition all apply." },
{ id:"c4-19", ch:"lib", src:"Ch 4 quiz Q19", type:"mc",
  q:"Which of the following properties is NOT a defining characteristic of living organisms?",
  options:["Breathes in Oxygen and releases Carbon Dioxide","Reproduces","Maintains Homeostasis","Has DNA and evolves"],
  answer:0, explain:"Plants, anaerobic bacteria, and many others do not breathe oxygen; the other three are universal." },
{ id:"c4-20", ch:"lib", src:"Ch 4 quiz Q20", type:"mc",
  q:"According to the short video on Trophic Cascades in Yellowstone National Park, why did bears become more abundant after wolves returned?",
  options:["Wolves diminished the herds of elk that actively drive bears away from their cubs.","Wolves changed the physical structure of the rivers which in turn encourages more fish for the bears to feed on.","Wolves scare away people that tend to disturb bears.","The decline in large herbivores that wolves preyed on led to increases in shrubs that produced berries the bears feed on."],
  answer:3, explain:"Fewer elk means more berry shrubs, a trophic cascade benefit for bears." },
{ id:"c4-21", ch:"lib", src:"Ch 4 quiz Q21 (answer cut off in PDF)", type:"mc",
  q:"According to the Trophic Cascades video, wolves were reintroduced into Yellowstone in _____ after how many years of absence?",
  options:["1995; about 70 years","1975; about 30 years","2005; about 50 years","1985; about 100 years"],
  answer:0, explain:"Wolves were reintroduced in 1995 after roughly 70 years (they were gone by the 1920s-30s). The PDF cut off the options; this is the standard answer." },

// ---------------- Chapter 7 (Populations and Communities) (17.5/21) ----------------
{ id:"c7-1", ch:"ch7", src:"Ch 7 quiz Q1 (essay, 0.5/2)", type:"essay", missed:true,
  q:"In your own words, explain why a K-strategist is likely to outcompete an r-strategist in an environment with shared limited resources.",
  you:"The K-strategist outcompetes the r-strategist because it invests more in fewer offspring and is better suited to stable, resource-limited environments.",
  model:"K-strategists are more specialized and efficient. Consequently they can live off less of the resource than the r-strategist and thus can diminish the resource level below the threshold that the r-strategist needs to thrive.",
  explain:"Instructor feedback: for full credit, highlight that at carrying capacity a K-strategist reduces the available critical resources to levels too low for r-strategists to thrive. Focusing just on parental care is insufficient." },
{ id:"c7-2", ch:"ch7", src:"Ch 7 quiz Q2", type:"mc",
  figure:"Old-field succession graph: breeding bird pairs per 100 acres and number of species vs ecological age (0-160 yr); stages bare field -> grassland -> grass/shrub -> pine forest (20-100 yr) -> oak-hickory climax (100+ yr). Both lines rise steeply from 0 to 20 years and flatten after about 100.",
  q:"During old-field succession, the graph shows that the number of species increases with time. During what period of time is this rate of increase the greatest?",
  options:["0-20 years","20-40 years","40-60 years","60-100 years","cannot be determined from this data."],
  answer:0, explain:"The steepest slope is in the first 20 years (bare field to grassland and shrubs)." },
{ id:"c7-3", ch:"ch7", src:"Ch 7 quiz Q3", type:"mc",
  q:"In the real world, many factors determine the numbers of organisms in any one population. Yet, a 'superfly' with unlimited food and no mortality would show what type of growth?",
  options:["Carrying capacity geometric increase","Irruptive growth","Exponential growth","Logistic growth","Malthusian growth"],
  answer:2, explain:"No limits = J curve exponential growth." },
{ id:"c7-4", ch:"ch7", src:"Ch 7 quiz Q4", type:"mc",
  q:"Predation is considered to be a(n) _______________ factor.",
  options:["Extrinsic","Intrinsic","Abiotic","Biotic","Extrinsic and biotic"],
  answer:4, explain:"It comes from outside the population (extrinsic) and is a living agent (biotic)." },
{ id:"c7-5", ch:"ch7", src:"Ch 7 quiz Q5", type:"mc",
  q:"Which of the following is a biotic population control mechanism?",
  options:["Nutrients","Precipitation","Day length","Climate","Pathogens"],
  answer:4, explain:"Pathogens are living; the others are abiotic." },
{ id:"c7-6", ch:"ch7", src:"Ch 7 quiz Q6", type:"mc",
  q:"Which of the following has a broader niche, a wider range of tolerance to environmental factors and therefore, better 'survivability'?",
  options:["an herbivore","a carnivore","a specialist","a generalist","an omnivore"],
  answer:3, explain:"Generalists tolerate a wide range of conditions and foods." },
{ id:"c7-7", ch:"ch7", src:"Ch 7 quiz Q7", type:"mc", missed:true, you:3,
  q:"The most common reason that introduced species cause trouble is because they",
  options:["Are larger than native species","Disrupt pre-existing niches","Are unusually efficient predators","Out compete the native species","None of these is correct"],
  answer:1, explain:"You answered 'out compete the native species.' The textbook's broader answer is that they disrupt pre-existing niches, which includes outcompeting but also preying on, infecting, or altering the habitat of natives." },
{ id:"c7-8", ch:"ch7", src:"Ch 7 quiz Q8", type:"mc", missed:true, you:1,
  figure:"Photo of a clear-cut hillside with slash on the ground and intact conifer forest behind it.",
  q:"In the coastal forest of Oregon an area was clear-cut for logging. Trees at the edge of the clearing and 200 meters into the forest died within a few months after the logging began. What is the best explanation for the death of the trees?",
  options:["The trees at the edge of the forest were more prone to disease","Abiotic edge effects, such as increased herbivory, negatively affected the trees","Increased sunlight, wind and temperature negatively affected the trees","The roots of all of the trees were damaged","Nitrogen fixing bacteria in the roots of the trees were killed"],
  answer:2, explain:"You answered B. Herbivory is a biotic factor, so 'abiotic edge effects such as herbivory' is self-contradictory. The real abiotic edge effects are sunlight, wind, and temperature." },
{ id:"c7-9", ch:"ch7", src:"Ch 7 quiz Q9", type:"mc",
  q:"Complexity in an ecological community has to do with the number of",
  options:["Species in the population","Species at each trophic level","Genetic variations within a species","Primary producers available","Primary producers relative to the number of consumers"],
  answer:1, explain:"Complexity = species per trophic level and number of levels; diversity = total species." },
{ id:"c7-10", ch:"ch7", src:"Ch 7 quiz Q10", type:"mc",
  q:"Total fertility rate refers to ________.",
  options:["the number of offspring born during a given year","the potential number of offspring born per female in her reproductive years","the average age at which females become sexually active","the number of offspring that survive to become reproductive adults","the number of females giving birth during a given year"],
  answer:1, explain:"TFR = expected lifetime births per female." },
{ id:"c7-11", ch:"ch7", src:"Ch 7 quiz Q11", type:"mc",
  q:"A biological community's productivity is a measure of",
  options:["Its number of species","The number of individuals in the community","Available solar energy that can be converted to biomass","The amount of biomass produced in the community","All of these are combined in measuring a community's productivity"],
  answer:3, explain:"Productivity is biomass produced per area per time." },
{ id:"c7-12", ch:"ch7", src:"Ch 7 quiz Q12", type:"mc",
  q:"The following statement: 'No two species can occupy the same niche and compete for the same resources for long' describes which ecological principle?",
  options:["Natural selection","Genetic drift","Competitive exclusion","Niche partitioning","antagonistic symbiosis"],
  answer:2, explain:"Gause's competitive exclusion principle." },
{ id:"c7-13", ch:"ch7", src:"Ch 7 quiz Q13", type:"mc",
  q:"Which of the following are pioneer species on recently glaciated rock?",
  options:["Herbs and shrubs","Lichens and mosses","Maples and redwoods","Spruce and fir trees","Evergreens and fir trees"],
  answer:1, explain:"Primary succession starts with lichens and mosses that build soil on bare rock." },
{ id:"c7-14", ch:"ch7", src:"Ch 7 quiz Q14", type:"mc",
  q:"Life expectancy is the",
  options:["Maximum life span that an individual of a given species could reach","Number of individuals in a population that survive in a given year","Number of years an individual of a certain age will probably live","Probability that an individual will survive infancy","All of these are descriptions of life expectancy"],
  answer:2, explain:"Option A is life span; option C is life expectancy." },
{ id:"c7-15", ch:"ch7", src:"Ch 7 quiz Q15", type:"mc",
  q:"Yellowstone scenario: wolves (a keystone species) were eradicated by the 1930s and elk populations exploded, causing a trophic cascade. With an overabundance of elk, the next population in the Yellowstone ecosystem to be directly affected was/were ________.",
  options:["mountain lion","wolves","plant species","beaver","songbird"],
  answer:2, explain:"Elk overbrowse willows and aspen first; beavers and songbirds decline afterward." },
{ id:"c7-16", ch:"ch7", src:"Ch 7 quiz Q16", type:"mc",
  q:"Mutualism is ________.",
  options:["a relationship between a beneficial predator and its prey","a relationship between two species in which both benefit","a relationship between two species in which only one benefits","a relationship with no benefits to either species","a relationship in which two species have a mutual predator"],
  answer:1, explain:"Both benefit (pollinators and flowers)." },
{ id:"c7-17", ch:"ch7", src:"Ch 7 quiz Q17", type:"mc",
  q:"In a commensal relationship,",
  options:["One species benefits while the other neither suffers nor benefits","One species benefits while the other suffers","Two species live together and both suffer","Two species live together and neither benefits nor suffers","Two species live together and both benefit"],
  answer:0, explain:"Commensalism: +/0. B is parasitism, E is mutualism." },
{ id:"c7-18", ch:"ch7", src:"Ch 7 quiz Q18", type:"mc",
  figure:"Photo of an elephant.",
  q:"Which of the following best describes the survivorship curve you would expect to find for the animal pictured here (an elephant)?",
  options:["late loss","constant loss","early loss","no loss"],
  answer:0, explain:"Elephants are K-strategists with Type I (late loss) survivorship." },
{ id:"c7-19", ch:"ch7", src:"Ch 7 quiz Q19", type:"mc", missed:true, you:2,
  figure:"Survivorship curves on a log scale: Type I (humans) stays high then drops late; Type II (birds) is a straight diagonal line; Type III (plants/trees) drops steeply at young ages then flattens.",
  q:"What does the survivorship figure illustrate?",
  options:["Birds have a constant mortality rate.","Humans have an increased mortality rate at a young age.","Plants have a decreased mortality rate at young age.","Plants have a steady rate of mortality change.","Birds have an ever decreasing mortality rate."],
  answer:0, explain:"You answered C. Plants (Type III) have very HIGH mortality when young. The straight line for birds (Type II) means a constant mortality rate at every age." },
{ id:"c7-20", ch:"ch7", src:"Ch 7 quiz Q20", type:"tf",
  q:"No two species can occupy the same niche and compete for the same resources for long.",
  options:["True","False"], answer:0,
  explain:"Competitive exclusion principle." },
{ id:"c7-21", ch:"ch7", src:"Ch 7 quiz Q21", type:"mc",
  figure:"Population growth rate vs temperature for three fish: Antarctic ice fish (narrow peak near 30 F), rainbow trout (about 50-75 F), desert pupfish (about 35-100 F).",
  q:"The species most likely to be affected if the water temperature increases from 74 F to 80 F would be ________.",
  options:["the Rainbow trout","the Desert pupfish","both the Desert pupfish and the Rainbow trout","neither the Desert pupfish or the Rainbow trout","the Antarctic ice fish, Rainbow trout, and the Desert pupfish"],
  answer:0, explain:"80 F is past the trout's upper tolerance limit but well inside the pupfish's range." },
{ id:"c7-22", ch:"ch7", src:"Ch 7 quiz Q22", type:"mc",
  q:"A community that changes very little over time is said to have great",
  options:["Renewal ability","Complexity","Diversity","Constancy","Connectedness"],
  answer:3, explain:"Constancy = stability over time; resilience = ability to recover." },
{ id:"c7-23", ch:"ch7", src:"Ch 7 quiz Q23", type:"mc",
  q:"When a population surpasses the carrying capacity of its environment, it is termed:",
  options:["overshoot","biotic potential","J curve","exponential growth"],
  answer:0, explain:"Overshoot is usually followed by a dieback." },
{ id:"c7-24", ch:"ch7", src:"Ch 7 quiz Q24", type:"mc",
  q:"What drives diversity down when disturbances are suppressed in an ecosystem?",
  options:["invasive species","competitive exclusion","keystone species","predators","Primary production"],
  answer:1, explain:"Without disturbance the best competitors exclude everyone else (intermediate disturbance hypothesis)." },
{ id:"c7-25", ch:"ch7", src:"Ch 7 quiz Q25", type:"mc",
  q:"Cheetahs can run extremely fast because",
  options:["They need to run extremely fast in order to catch their prey","An ancestor that was able to run fast had an advantage and passed those genes on to its offspring","Over time they gradually built up speed as they adapted to faster and faster prey species","They are competing with stronger lions and hyenas for their food so they need to be fast","All of these are reasons cheetahs can run extremely fast"],
  answer:1, explain:"Natural selection on existing variation; need does not cause adaptation (that is Lamarckian)." },
{ id:"c7-26", ch:"ch7", src:"Ch 7 quiz Q26", type:"mc",
  q:"What makes up an ecological community?",
  options:["Species that use the same resources","All the plants, animals and organisms interacting in a specific area","Different species of the same type of animal within a specific area","All the plants, animals and organisms in the biome","All the plants, animals and organisms in the ecosystem"],
  answer:1, explain:"Community = all interacting populations in an area (biotic only)." },
{ id:"c7-27", ch:"ch7", src:"Ch 7 quiz Q27", type:"mc",
  q:"Intraspecific competition is competition among ________ for resources.",
  options:["Predators and prey","Both plants and animals","Producers, consumers and detritivores","Members of different species","Members of a single species"],
  answer:4, explain:"Intra = within one species; inter = between species." },
{ id:"c7-28", ch:"ch7", src:"Ch 7 quiz Q28", type:"mc",
  q:"As ecological development (succession) proceeds, a biological community",
  options:["Gradually stagnates","Becomes more diverse","Goes through repeated secondary succession stages","Goes through repeated primary succession stages","Becomes less complex"],
  answer:1, explain:"Species richness rises through succession toward the climax." },
{ id:"c7-29", ch:"ch7", src:"Ch 7 quiz Q29", type:"mc",
  q:"Which of the following types of population growth patterns would best represent a group of elephants that enter a new, open habitat and become a stable part of that ecosystem?",
  options:["Exponential growth","Irruptive growth","Malthusian growth","Chaotic or catastrophic growth","Logistic growth"],
  answer:4, explain:"Grows then stabilizes at K: an S curve." },
{ id:"c7-30", ch:"ch7", src:"Ch 7 quiz Q30", type:"mc",
  q:"By what mechanism do heritable variations arise in a population?",
  options:["mutations","resource partitioning","radiative evolution","tolerance avoidance"],
  answer:0, explain:"Mutation is the ultimate source of new alleles." },
{ id:"c7-31", ch:"ch7", src:"Ch 7 quiz Q31", type:"mc",
  figure:"MacArthur's warblers: each of five warbler species feeds in a different region of a spruce tree (shown in red). The Myrtle warbler's region is the largest, spanning the lower and middle tree.",
  q:"Using only the information provided by this figure, which species of warbler appears to have the greatest competitive advantage?",
  options:["Cape May warbler","Bay-breasted warbler","Black-throated warbler","Blackburnian warbler","Myrtle warbler"],
  answer:4, explain:"The Myrtle warbler uses the largest share of the tree, so it has the widest feeding niche." },
{ id:"c7-32", ch:"ch7", src:"Ch 7 quiz Q32", type:"mc",
  q:"Natural selection will ultimately make a species",
  options:["More intelligent","Physically bigger","Better adapted to its environment","More aggressive","Less vulnerable to its predators"],
  answer:2, explain:"Selection favors whatever increases fitness in that environment, not any particular trait." },
{ id:"c7-33", ch:"ch7", src:"Ch 7 quiz Q33", type:"mc",
  q:"Survivorship is determined by",
  options:["The percentage of a cohort that survives to a certain age","Number of individuals in a population that survive in a given year","Number of years an individual of a certain age will probably live","Probability that an individual will survive infancy","Maximum life span that an individual of a given species could reach"],
  answer:0, explain:"Survivorship tracks a cohort over its lifetime." },
{ id:"c7-34", ch:"ch7", src:"Ch 7 quiz Q34", type:"mc", missed:true, you:2,
  q:"Regular lawn mowing selects for short-headed rather than tall-headed dandelions because",
  options:["Tall flowers spread their seeds farther","Tall flowers cannot reproduce","Short flowers can reproduce","Short flowers spread their seeds farther","Short flowers have less competition when the lawn is mowed often"],
  answer:1, explain:"You answered 'short flowers can reproduce.' Selection works by removing the unfit: tall flowers get cut off before setting seed, so they cannot reproduce. That is what shifts the population toward short heads." },
{ id:"c7-35", ch:"ch7", src:"Ch 7 quiz Q35", type:"mc",
  q:"The form of display in which several organisms evolve to look alike due to similar toxicity is known as?",
  options:["Mullerian Mimicry","Batesian Mimicry","Camouflage","Hybridization","Niche convergence"],
  answer:0, explain:"Mullerian: several toxic species share warning colors. Batesian: a harmless mimic copies a toxic model." },
{ id:"c7-36", ch:"ch7", src:"Ch 7 quiz Q36", type:"mc",
  q:"Which of the following illustrates a population that is stable and has not reached the carrying capacity of its environment?",
  options:["J curve graph","overshoot graph","S curve graph","straight-line graph"],
  answer:2, explain:"The quiz key is the S (logistic) curve, which levels off smoothly without overshooting." },
{ id:"c7-37", ch:"ch7", src:"Ch 7 quiz Q37", type:"mc",
  q:"Some plants produce toxins that inhibit the growth of other plants. This is an example of",
  options:["Interspecific competition","Predator-prey interactions","Commensalism","Parasitism","Inhibition"],
  answer:4, explain:"Inhibition (allelopathy), e.g., black walnut." },
{ id:"c7-38", ch:"ch7", src:"Ch 7 quiz Q38", type:"mc",
  q:"The population size where births and deaths are equal and thus the population is stable is known as",
  options:["Carrying capacity","Symbiosis","Biotic potential","Overshoot"],
  answer:0, explain:"K, the carrying capacity." },

// ---------------- Quiz - Evolution (20.41/21) ----------------
{ id:"c5-1", ch:"ch5", src:"Evolution quiz Q1", type:"match",
  q:"Match the term to the explanation.",
  pairs:[
    { p:"The method of classification that groups organisms by common ancestry.", a:"Cladistics" },
    { p:"A measure of the number of offspring an individual produces that survive to reproduce.", a:"Fitness" },
    { p:"Environmental gradients that lead to maintenance of gene variety.", a:"Cline" },
    { p:"An example of this is the diversity of Galapagos finches that all derive from a single common ancestor.", a:"Adaptive radiation" },
    { p:"A phenomenon when a small subpopulation arrives in a new habitat with a different allelic frequency than the source population.", a:"Founder effect" },
    { p:"A process that often occurs via disruptive selection acting on a single population.", a:"Sympatric speciation" }
  ],
  explain:"This matching set appeared twice (Q1 and Q12). On Q12 you matched 'disruptive selection acting on a single population' to Founder effect; the answer is Sympatric speciation (speciation without geographic separation)." },
{ id:"c5-2", ch:"ch5", src:"Evolution quiz Q2", type:"mc",
  q:"If an environment changes rapidly, organisms with ____ will be more likely to survive and reproduce.",
  options:["existing beneficial mutations","existing neutral mutations","the ability to produce beneficial mutations","the ability to adapt their genotype","the correct allele frequency"],
  answer:0, explain:"Selection works on variation that already exists; organisms cannot produce mutations on demand or change their genotype." },
{ id:"c5-3", ch:"ch5", src:"Evolution quiz Q3", type:"mc",
  q:"The type of reproductive isolation in which two populations live in the same habitat but remain isolated from one another due to one being active during the daytime only and the other being active only during the night is",
  options:["behavioral isolation.","gametic isolation.","mechanical isolation.","temporal isolation.","sexual selection."],
  answer:3, explain:"Temporal = time based." },
{ id:"c5-4", ch:"ch5", src:"Evolution quiz Q4", type:"mc",
  q:"If the average leg size of a reptile continually got smaller through generations, this would be an example of",
  options:["disruptive selection.","stabilizing selection.","directional selection.","genetic drift.","bottleneck effect."],
  answer:2, explain:"One extreme is favored and the mean shifts steadily (eventually, snakes)." },
{ id:"c5-5", ch:"ch5", src:"Evolution quiz Q5", type:"mc",
  q:"Historically fishermen kept larger fish and left smaller juvenile fish. Over time the average size of the fish would",
  options:["increase by natural selection.","decrease by genetic drift.","decrease by natural selection.","increase by genetic drift.","remain unchanged."],
  answer:2, explain:"Fishing is a selective force that removes large fish before they reproduce: directional selection for smaller size." },
{ id:"c5-6", ch:"ch5", src:"Evolution quiz Q6", type:"mc",
  q:"Two species of finches found on the same Galapagos island, but feeding on different food sources, is an example of ____ speciation.",
  options:["allopatric","sympatric","prezygotic","postzygotic","parapatric"],
  answer:1, explain:"Same place (sym-patric), split by resource use." },
{ id:"c5-7", ch:"ch5", src:"Evolution quiz Q7", type:"mc",
  figure:"Three graphs of survival of young vs clutch size over time; the distribution narrows around 4-5 eggs (stabilizing selection).",
  q:"The figure represents stabilizing selection. What happens when an individual is produced that possesses a trait far away from the mean value?",
  options:["That extreme individual will likely not survive and reproduce.","That extreme individual will be more likely to survive and reproduce.","That extreme individual will have neither an advantage nor a disadvantage than other individuals.","All phenotypes have equal likelihood of surviving and reproducing.","The average phenotype is less likely to survive and reproduce."],
  answer:0, explain:"Stabilizing selection selects against individuals far from the mean." },
{ id:"c5-8", ch:"ch5", src:"Evolution quiz Q8", type:"mc",
  q:"Evolution occurs as a result of",
  options:["the discovery of a desirable characteristic in a population.","an individual's physiological modification.","environmental change that forces modification in a resident species.","better survival or reproduction rates by individuals with a particular characteristic.","a population's physiological modification."],
  answer:3, explain:"Differential reproductive success is the engine." },
{ id:"c5-9", ch:"ch5", src:"Evolution quiz Q9", type:"mc",
  q:"Which of the following is not part of Darwin's theory of natural selection?",
  options:["Offspring are like their parents.","There is variation between individuals within a species.","Fewer offspring are produced each generation than can be supported by the environment.","Some individuals have a higher chance of surviving and reproducing than others in the same population.","Heritable characteristics can be passed from parent to offspring."],
  answer:2, explain:"Darwin's premise is overproduction: MORE offspring than the environment can support." },
{ id:"c5-10", ch:"ch5", src:"Evolution quiz Q10", type:"mc",
  q:"A male peacock has enormous tail feathers that it uses in mating displays to attract females. While the tail feathers are an advantage in mating, what is the potential disadvantage of these feathers to the male?",
  options:["The feathers require a lot of energy to produce.","Bright feathers make males less susceptible to predation.","The feathers make the male more attractive to other males.","There are no disadvantages to having large tail feathers.","The large tail feathers would make it easier to fly."],
  answer:0, explain:"Sexual selection trades survival costs (energy, predation) for mating success." },
{ id:"c5-11", ch:"ch5", src:"Evolution quiz Q11", type:"mc",
  q:"In what type of environment is being heterozygous in regards to the sickle cell trait an advantage?",
  options:["An environment that has malaria.","An environment that is malaria free.","Environment that is exposed to a large amount of sunlight year round.","Environments that are degraded.","Cold and rainy environments favor the heterozygote."],
  answer:0, explain:"Heterozygote advantage: carriers' red blood cells resist the malaria parasite." },
{ id:"c5-12", ch:"ch5", src:"Evolution quiz Q12 (0.42/0.5)", type:"match", missed:true,
  q:"Match the term to the explanation (repeat of Q1; you missed one pair).",
  pairs:[
    { p:"The method of classification that groups organisms by common ancestry.", a:"Cladistics" },
    { p:"A measure of the number of offspring an individual produces that survive to reproduce.", a:"Fitness" },
    { p:"Environmental gradients that lead to maintenance of gene variety.", a:"Cline" },
    { p:"An example of this is the diversity of Galapagos finches that all derive from a single common ancestor.", a:"Adaptive radiation" },
    { p:"A phenomenon when a small subpopulation arrives in a new habitat with a different allelic frequency than the source population.", a:"Founder effect" },
    { p:"A process that often occurs via disruptive selection acting on a single population.", a:"Sympatric speciation" }
  ],
  explain:"You matched the last prompt to Founder effect. Disruptive selection on one population splits it into two without geographic separation: sympatric speciation." },
{ id:"c5-13", ch:"ch5", src:"Evolution quiz Q13", type:"mc",
  q:"Which of the following is most likely to lead to two distinct species?",
  options:["directional selection","stabilizing selection","disruptive selection","genetic drift","bottleneck effect"],
  answer:2, explain:"Disruptive selection divides a single population into two." },
{ id:"c5-14", ch:"ch5", src:"Evolution quiz Q14", type:"mc",
  q:"A female peacock chooses a male as a mate based on his showy plumage and courtship dance. This is an example of",
  options:["random mating.","assortative mating.","sexual selection.","gene flow.","natural selection."],
  answer:2, explain:"Mate choice based on traits = sexual selection." },
{ id:"c5-15", ch:"ch5", src:"Evolution quiz Q15", type:"mc",
  q:"One concern of conservation biologists is that endangered species will have low genetic diversity due to a small population size. Why is this a concern?",
  options:["Individuals in small populations acquire mutations more slowly than those in large populations.","Sexual selection is stronger in small populations.","If the environment changes, individuals will not be able to change their alleles and survive.","If a disease occurs in the population, there may not be organisms with resistant alleles.","Allele frequencies are lower in smaller populations."],
  answer:3, explain:"Low diversity means no raw material for selection when conditions change." },
{ id:"c5-16", ch:"ch5", src:"Evolution quiz Q16", type:"mc",
  q:"Fitness refers to",
  options:["the variation in traits within the population.","reproductive success.","mutations that benefit an organism's survival.","the physical health of an individual.","the physical health of a population."],
  answer:1, explain:"Fitness is measured in surviving offspring, not strength or health." },
{ id:"c5-17", ch:"ch5", src:"Evolution quiz Q17", type:"mc",
  q:"What characteristic do a bottleneck and a founder effect have in common?",
  options:["Both encounter a population crash.","Both involve a portion of a population becoming isolated.","Both involve a decrease in a population's genetic diversity.","Both affect the entire population.","Both are a type of natural selection."],
  answer:2, explain:"Both are forms of genetic drift that reduce diversity." },
{ id:"c5-18", ch:"ch5", src:"Evolution quiz Q18", type:"mc",
  q:"A population of bacteria is in Hardy-Weinberg equilibrium. However, through repeated exposure to an antibiotic, the frequency of the recessive allele is rapidly increasing. What is the most likely explanation for this response?",
  options:["The recessive allele is responsible for susceptibility of the bacteria to the antibiotic.","The dominant allele is responsible for susceptibility of the bacteria to the antibiotic.","The recessive allele is responsible for resistance of the bacteria to the antibiotic.","The population is experiencing gene flow.","The population is experiencing disruptive selection."],
  answer:2, explain:"An allele rising under a selective agent must confer the adaptive phenotype (resistance)." },
{ id:"c5-19", ch:"ch5", src:"Evolution quiz Q19", type:"mc",
  q:"According to Darwin, natural selection usually",
  options:["neither preserves nor rejects harmful variations in a population.","preserves harmful variations and rejects favorable variations in a population.","preserves favorable and harmful variations in a population.","preserves favorable variations and rejects harmful variations in a population."],
  answer:3, explain:"Darwin's own phrasing." },
{ id:"c5-20", ch:"ch5", src:"Evolution quiz Q20", type:"mc",
  figure:"Cladogram: amphibians branch first, then mammals, then turtles, lizards and snakes, crocodiles, nonavian dinosaurs, and birds (birds and nonavian dinosaurs share the most recent node). 'Class Reptilia' without birds is labeled paraphyletic.",
  q:"Based on the cladogram, birds are most closely related to",
  options:["crocodiles.","snakes.","mammals.","dinosaurs.","amphibians."],
  answer:3, explain:"Birds share their most recent common ancestor with nonavian dinosaurs." },
{ id:"c5-21", ch:"ch5", src:"Evolution quiz Q21", type:"mc",
  q:"The type of reproductive isolation in which the two populations are separated due to their habitat is",
  options:["mechanical isolation.","ecological isolation.","hybrid inviability.","behavioral isolation.","temporal isolation."],
  answer:1, explain:"Ecological = habitat isolation." },
{ id:"c5-22", ch:"ch5", src:"Evolution quiz Q22", type:"mc",
  q:"Birds use specific songs, coloring, and mating dances to attract mates of their species. This is an example of ____ reproductive isolation.",
  options:["postzygotic","allopatric","prezygotic","sympatric","parapatric"],
  answer:2, explain:"Behavioral isolation acts before fertilization, so it is prezygotic." },
{ id:"c5-23", ch:"ch5", src:"Evolution quiz Q23", type:"mc",
  q:"In the process of natural selection, the organisms most likely to survive are ________.",
  options:["the organisms that are most reproductively fit","the organisms that have a range of reproductive fitness","the organisms that survive at various ranges of tolerance of temperature","the organisms that can adapt to an extreme range of tolerance of precipitation","the organisms that are very large and very small that outlive the average sized organisms"],
  answer:0, explain:"Fitness = reproductive success." },
{ id:"c5-24", ch:"ch5", src:"Evolution quiz Q24", type:"mc",
  q:"A single common ancestor evolving into the current 28 species of silversword plants found on the Hawaiian islands is an example of",
  options:["gradualism.","punctuated equilibrium.","extinction.","a prezygotic barrier to evolution.","adaptive radiation."],
  answer:4, explain:"One ancestor radiating into many niches = adaptive radiation." },
{ id:"c5-25", ch:"ch5", src:"Evolution quiz Q25", type:"mc",
  figure:"Phylogenetic tree: U is the root; V is the node where X splits from the (Y, Z) branch; W is the node where Y and Z split.",
  q:"In the figure, the letter W represents which of the following?",
  options:["the common ancestor for Y and Z","the common ancestor for U","the ancestor for Z","the common ancestor for X and Y","the common ancestor for X, Y, and Z"],
  answer:0, explain:"W is the node from which Y and Z branch; V is the common ancestor of X, Y, and Z." },
{ id:"c5-26", ch:"ch5", src:"Evolution quiz Q26", type:"mc",
  q:"The scientist who published 'On the Origin of Species by Means of Natural Selection' in 1859 was",
  options:["James Hutton.","Jean Lamarck.","Georges Buffon.","Charles Darwin.","Charles Lyell."],
  answer:3, explain:"Darwin (Wallace independently proposed natural selection the year before)." },
{ id:"c5-27", ch:"ch5", src:"Evolution quiz Q27", type:"mc",
  q:"When comparing chick and pig embryos, the similar eyes, pharyngeal pouches, and post-anal tails are evidence of ___________.",
  options:["analogy","convergent evolution","common ancestry","biogeography","artificial selection"],
  answer:2, explain:"Shared embryonic structures are homologies inherited from a common ancestor." },
{ id:"c5-28", ch:"ch5", src:"Evolution quiz Q28", type:"mc",
  q:"How might an evolutionary biologist explain why a species of birds has evolved a larger beak size?",
  options:["Large beak size occurred as a result of mutation in each member of the population.","The ancestors encountered a tree with larger seeds. They needed to develop larger beaks in order to eat the larger seeds, and over time, they adapted to meet this need.","Some members of the ancestral population had larger beaks than others. If larger beak size was advantageous, they would be more likely to survive and reproduce. As such, large-beaked birds increased in abundance through inheritance and reproduction relative to small-beaked birds.","The ancestors discovered that by stretching their beaks, the beaks would get longer, and this increase was passed on to their offspring."],
  answer:2, explain:"Selection on existing variation. B and D are Lamarckian; A is wrong because mutations are individual and random." },
{ id:"c5-29", ch:"ch5", src:"Evolution quiz Q29", type:"mc", missed:true, you:0,
  figure:"Diagram titled Habitat Isolation: an original population splits into two groups that use different patches (micro-spatial, 'patchy habitat') or different habitats (macro-spatial, 'habitat 1' vs 'habitat 2') in the same region, leading to speciation.",
  q:"What mechanism of reproductive isolation is described in this image (populations diverging by using different habitats or patches within the same region)?",
  options:["Geographic isolation","Behavior isolation","Temporal isolation","Ecological isolation","Mechanical isolation"],
  answer:3, explain:"You answered geographic isolation. The diagram is labeled habitat isolation and shows populations in the same region choosing different habitats or patches, with no physical barrier. Separation by habitat is ecological isolation; geographic isolation requires a physical barrier such as a river or mountain." },
{ id:"c5-30", ch:"ch5", src:"Evolution quiz Q30", type:"mc",
  q:"What fundamentally changes during biological evolution?",
  options:["DNA sequences","Cells","Phenotypes","proteins"],
  answer:0, explain:"Evolution is change in the genetic (DNA) makeup of a population." },
{ id:"c5-31", ch:"ch5", src:"Evolution quiz Q31", type:"mc",
  q:"If two similar species are placed in an experimental environment to compete for survival, which would you expect to perform better in the context of evolution?",
  options:["The larger species.","The more intelligent species.","The species that can produce more successful offspring.","The species that consumes more resources."],
  answer:2, explain:"Evolutionary success is reproductive success." },
{ id:"c5-32", ch:"ch5", src:"Evolution quiz Q32", type:"mc",
  q:"The form of speciation where the ancestor is gradually replaced by the descendant population is called ____, while in contrast, _____ speciation produces multiple descendant populations.",
  options:["cladogenesis; anagenesis","anagenesis; cladogenesis","convergence; parsimony","directional; disruptive","homologous; homoplastic"],
  answer:1, explain:"Ana = transformation of one lineage; clado = branching." },
{ id:"c5-33", ch:"ch5", src:"Evolution quiz Q33", type:"mc",
  figure:"Drawing comparing the wing skeletons of a pterodactyl, a bat, and a bird.",
  q:"Pterosaurs are an extinct lineage of reptiles that coexisted with dinosaurs during the Mesozoic. They share similar membranous wings with modern-day bats (a mammal). What evolutionary process produced this similarity?",
  options:["Common ancestry","Cladogenesis","Anagenesis","Convergent evolution","Mimicry"],
  answer:3, explain:"Reptile and mammal wings evolved independently: a homoplasy from convergent evolution." },
{ id:"c5-34", ch:"ch5", src:"Evolution quiz Q34", type:"mc",
  q:"The variation natural selection operates on is due to random mutations. What does this imply about natural selection?",
  options:["Natural selection is also a random process.","Natural selection is nevertheless a directed process - the likelihood one variant will be favored in a given environment over another is predictable, even if the origin of the variant is not.","There is no possibility God could be involved in this process.","A, B and C are all true.","None of the above."],
  answer:1, explain:"Mutation is random; selection is not." },
{ id:"c5-35", ch:"ch5", src:"Evolution quiz Q35", type:"mc",
  figure:"Phylogeny: Tomato and Fern branch off first (node b); then Sponge (node c); then Mouse and Mushroom share node d/e as the closest pair.",
  q:"Using the provided phylogeny, which of the following statements is correct?",
  options:["The mouse is more closely related to the mushroom than the sponge.","The fern is more closely related to the sponge than to the mushroom.","The sponge is more closely related to a mouse than to a fern.","The tomato is equally related to the mouse and mushroom."],
  answer:2, explain:"The quiz key is C: sponge and mouse (both animals) share a more recent ancestor than sponge and fern." },
{ id:"c5-36", ch:"ch5", src:"Evolution quiz Q36", type:"mc",
  q:"Which biological process creates new traits in offspring?",
  options:["Natural selection","Differential survival","Sexual selection","Genetic Mutations"],
  answer:3, explain:"Selection only sorts existing traits; mutation creates new ones." },

// ---------------- Chapter 6 and 11 - Biomes and Biodiversity (14.49/17) ----------------
{ id:"c6-1", ch:"ch6_11", src:"Ch 6/11 quiz Q1 (2.5/3)", type:"match", missed:true,
  q:"Match the acronym or abbreviation to the correct description.",
  pairs:[
    { p:"IUCN", a:"This organization supports the list of threatened and endangered species." },
    { p:"CITES", a:"This treaty regulates the trade of threatened and endangered species." },
    { p:"USFWS", a:"United States agency responsible for managing wild habitats on federal lands." },
    { p:"SSP", a:"Programs designed to recover populations of endangered flora and fauna usually through captive breeding." },
    { p:"ESA", a:"Key legislative mechanism in the United States designed to identify and protect endangered species." },
    { p:"MBTA", a:"Key legislative device used specifically to protect migrating birds of North America." }
  ],
  explain:"You matched SSP to the IUCN description. SSP = Species Survival Plan, the zoo captive-breeding programs. IUCN keeps the Red List." },
{ id:"c6-2", ch:"ch6_11", src:"Ch 6/11 quiz Q2", type:"match",
  q:"Match the image description to the most appropriate terrestrial habitat.",
  pairs:[
    { p:"An elephant among dry grass and scattered shrubs", a:"Savannah" },
    { p:"A field of grass and flowers", a:"Prairie" },
    { p:"Winter scene of pines", a:"Boreal" },
    { p:"Mountains with snow", a:"Alpine" },
    { p:"A variety of trees with dense understory plants", a:"Rainforest" },
    { p:"A boardwalk through a sparsely wooded field", a:"Bog" }
  ],
  explain:"Biome recognition. Savanna = tropical grassland with scattered trees and large grazers; boreal = northern conifers; bog = peat wetland." },
{ id:"c6-3", ch:"ch6_11", src:"Ch 6/11 quiz Q3 (1/3)", type:"match", missed:true,
  q:"Match the biodiversity term to the appropriate image (described in words).",
  pairs:[
    { p:"Prokaryote", a:"Anabaena at 1000x (a chain of bead-like cells)" },
    { p:"Hyphae", a:"Fungal mycelium (tangled threads)" },
    { p:"Strobilus", a:"Lycopodium with yellow cone-like tips" },
    { p:"Carpel", a:"Lily ovary cross section" },
    { p:"Ovule", a:"Pine female strobilus at 100x (section through a cone)" },
    { p:"Gametophyte", a:"Fern prothallus (small heart-shaped green plate)" }
  ],
  explain:"You got prokaryote and hyphae right and swapped the last four: strobilus = a cone (Lycopodium); carpel = the female flower part, seen as the lily ovary; ovule = the egg-bearing structure visible inside the pine cone section; gametophyte = the haploid fern prothallus." },
{ id:"c6-4", ch:"ch6_11", src:"Ch 6/11 quiz Q4", type:"mc",
  q:"A soft body usually enclosed by a hard shell is a characteristic of some",
  options:["mollusks.","arthropods.","insects.","vertebrates."],
  answer:0, explain:"Snails, clams, and relatives." },
{ id:"c6-5", ch:"ch6_11", src:"Ch 6/11 quiz Q5", type:"mc",
  q:"Single-celled organisms having cell walls and no nucleus are found in the Domain(s)",
  options:["Eucarya.","Eucarya and Bacteria.","Bacteria and Archaea.","Eucarya and Archaea."],
  answer:2, explain:"No nucleus = prokaryote = Bacteria and Archaea." },
{ id:"c6-6", ch:"ch6_11", src:"Ch 6/11 quiz Q6", type:"mc",
  q:"The most successful animal phylum in regards to diversity and numbers is",
  options:["Mollusca.","Nematoda.","Platyhelminthes.","Arthropoda.","Echinodermata."],
  answer:3, explain:"Insects alone account for most described animal species." },
{ id:"c6-7", ch:"ch6_11", src:"Ch 6/11 quiz Q7", type:"mc",
  q:"Which of the following is an example of a prokaryote?",
  options:["Plants","Bacteria","Fungi","Algae","Protozoa"],
  answer:1, explain:"All the others are eukaryotes." },
{ id:"c6-8", ch:"ch6_11", src:"Ch 6/11 quiz Q8", type:"mc",
  q:"A fungus",
  options:["is an autotroph.","lacks cell walls.","produces spores.","has a cellulose cell wall."],
  answer:2, explain:"Fungi are heterotrophs with chitin cell walls that reproduce by spores." },
{ id:"c6-9", ch:"ch6_11", src:"Ch 6/11 quiz Q9", type:"mc",
  q:"Which of the following characteristics do all animals share?",
  options:["They are single-celled eukaryotes.","They are multi-cellular prokaryotes.","They are multi-cellular eukaryotes.","They are single-celled prokaryotes."],
  answer:2, explain:"Animals are multicellular, eukaryotic heterotrophs." },
{ id:"c6-10", ch:"ch6_11", src:"Ch 6/11 quiz Q10", type:"mc",
  q:"An invertebrate is an animal that",
  options:["does not have a backbone.","has a backbone.","has a complete digestive tract.","has an incomplete digestive tract.","does not have true tissues."],
  answer:0, explain:"In- (without) vertebrae." },
{ id:"c6-11", ch:"ch6_11", src:"Ch 6/11 quiz Q11", type:"mc",
  q:"In pine, there is a dominant ____ generation.",
  options:["sporophyte","gametophyte"],
  answer:0, explain:"The pine tree is the diploid sporophyte; the gametophyte is tiny and inside the cone. (The rest of this quiz was cut off in the PDF.)" },

// ---------------- Conservation, Landscape & Restoration Quiz (19.5/21) ----------------
{ id:"cc-1", ch:"cons", src:"Conservation quiz Q1", type:"mc",
  q:"The equilibrium model of island biogeography explains diversity on islands as a balance between",
  options:["speciation and extinction.","immigration and extinction.","speciation and emigration.","immigration and emigration.","speciation and immigration."],
  answer:1, explain:"MacArthur and Wilson: species arrive (immigration) and disappear (extinction)." },
{ id:"cc-2", ch:"cons", src:"Conservation quiz Q2", type:"mc",
  q:"According to the article on Restoring Wetlands, which of the following explains why the cord-grass will not grow sufficiently long to support clapper rails?",
  options:["insufficient soil nutrients.","limited predatory beetle population that preys on scale insects","over abundance of herbivorous scale insect","insufficient grass density to retain soil nutrients","all the above"],
  answer:4, explain:"All four problems interacted in the Sweetwater Marsh restoration." },
{ id:"cc-3", ch:"cons", src:"Conservation quiz Q3", type:"mc",
  q:"What shape of park is preferable for minimizing edge effects?",
  options:["Square","Circular","Linear","Fragmented","Oval"],
  answer:1, explain:"A circle has the least perimeter per unit area." },
{ id:"cc-4", ch:"cons", src:"Conservation quiz Q4", type:"mc",
  q:"The element within the landscape that is most continuous is called the _______.",
  options:["patch","mosaic","matrix","medium","substrate"],
  answer:2, explain:"Patches are embedded in the matrix." },
{ id:"cc-5", ch:"cons", src:"Conservation quiz Q5", type:"mc",
  q:"Replanting forests after they have been cut down for human use is one conservation tactic. However, replanted forests are different from native forests because:",
  options:["The forest has similar diversity but grows very slowly.","The newly planted trees grow faster than natural forest but are re-harvested.","The newly planted forests usually are monocultures.","Trees are spaced uniformly which decreases wildlife use."],
  answer:2, explain:"Plantations are single-species, single-age stands with little diversity." },
{ id:"cc-6", ch:"cons", src:"Conservation quiz Q6", type:"mc",
  q:"Many bird species that were locally extinct have been successfully re-introduced to their native ranges (California condors, peregrine falcons). This re-introduction was made possible by:",
  options:["removal of monoculture forest, providing better nesting sites for hatchlings","allowing 'controlled' burning to remove invasive species and improve soil","captive breeding programs that produced enough birds to use at re-population sites","removing pollutants from streams and rivers (particularly DDT)"],
  answer:2, explain:"Captive breeding (Species Survival Plans) produced the birds; banning DDT helped but did not produce the birds." },
{ id:"cc-7", ch:"cons", src:"Conservation quiz Q7", type:"mc",
  q:"Which of the following is NOT true regarding coastal marshes?",
  options:["they reduce coastal storm surges","they provide root mats that stabilize the ground","they provide critical habitat for California's giant redwoods","they provide nurseries for fish, birds and shrimp","they allow inland areas to become less salty"],
  answer:2, explain:"Redwoods live in temperate rainforest, not salt marshes." },
{ id:"cc-8", ch:"cons", src:"Conservation quiz Q8", type:"mc",
  q:"Which of the following statements is true regarding nature protection?",
  options:["early efforts consisted of efforts to use resources sustainably; now efforts are aimed at restoring and rehabilitating","intervention is used to discourage/reduce undesired organisms","reclamation cleans and repairs severely degraded ecosystems","mitigation is used to replace degraded sites with areas of equal ecological value","all of the above"],
  answer:4, explain:"Each statement is a correct definition." },
{ id:"cc-9", ch:"cons", src:"Conservation quiz Q9", type:"mc",
  q:"When all of the trees in a particular area are all harvested at the same time it is known as:",
  options:["selective harvesting","clear-cutting","timber concession","afforestation"],
  answer:1, explain:"Clear-cutting removes everything at once." },
{ id:"cc-10", ch:"cons", src:"Conservation quiz Q10", type:"mc",
  q:"One of the reasons that it is difficult to restore an oak savanna is that",
  options:["Too many weedy species take over the oak saplings","There are no natural fires to control vegetation","Too many trees are cut down illegally for their timber value","Too many wild animals destroy the bark of the trees","There is not enough suitable land remaining"],
  answer:1, explain:"Savannas are fire-maintained; without fire, woody plants take over." },
{ id:"cc-11", ch:"cons", src:"Conservation quiz Q11", type:"tf",
  q:"The loss of forests can affect rainfall patterns.",
  options:["True","False"], answer:0,
  explain:"Forests recycle water through transpiration." },
{ id:"cc-12", ch:"cons", src:"Conservation quiz Q12", type:"mc",
  q:"Which one of the following choices is not related to the recent approach of establishing megareserves as a preferred conservation strategy?",
  options:["The amount of pristine habitat available is limited.","Incorporating local land use is important in management of large tracts of land.","It is more effective to focus on preserving particular species and not whole ecosystems.","A megareserve includes a central area of pristine habitat and surrounding land where some human disturbance is permitted.","Corridors of dispersal are used to provide links between pristine areas."],
  answer:2, explain:"Megareserves are an ecosystem-level approach, not single-species." },
{ id:"cc-13", ch:"cons", src:"Conservation quiz Q13", type:"mc",
  q:"Which of the following is not an indirect contribution of forests?",
  options:["Use of wood for building infrastructure.","Provide habitat for biodiversity.","Play an essential role in regulating local climates.","Play an essential role in the storage of carbon."],
  answer:0, explain:"Wood products are a direct use; the others are indirect ecological services." },
{ id:"cc-14", ch:"cons", src:"Conservation quiz Q14", type:"mc",
  q:"Which of the following preservation tactics would have the greatest impact on saving the largest number of species?",
  options:["Preserve a large tract of land that contains source populations of keystone species.","Preserve several small tracts of land that contain source populations of keystone species.","Preserve a large tract of land that contains sink populations of keystone species.","Preserve a large tract of land that contains source populations of flagship species.","Preserve multiple small tracts of land that each contain source populations of keystone species."],
  answer:0, explain:"Large (SLOSS), source (not sink) populations, keystone (not merely flagship) species." },
{ id:"cc-15", ch:"cons", src:"Conservation quiz Q15", type:"mc",
  figure:"Bar graph of wood use by continent (fuelwood vs lumber vs paper fiber).",
  q:"Which of the following continents is using the least harvested wood for fuel?",
  options:["South America","North America","Europe","Asia","Africa"],
  answer:2, explain:"Europe burns the smallest share of its harvest; Africa and Asia burn the most." },
{ id:"cc-16", ch:"cons", src:"Conservation quiz Q16", type:"mc",
  q:"What, if any, is the relationship between deforestation and turbidity of local streams and rivers?",
  options:["As deforestation increases, turbidity decreases.","As deforestation decreases, turbidity increases.","As deforestation increases, turbidity increases.","There is no scientific evidence that they are related to each other."],
  answer:2, explain:"Bare soil erodes into streams, making them cloudy." },
{ id:"cc-17", ch:"cons", src:"Conservation quiz Q17", type:"mc",
  q:"Why is there a need to reeducate people about the role of fire in natural systems?",
  options:["People are still throwing away cigarette butts that can start forest fires","People who camp are not putting their campfires out causing fires in inaccessible areas","People do not understand that fire is a natural part of many biological ecosystems","People are well educated about fire and do not need to be reeducated","People are starting fires in wilderness areas to make the area available for logging"],
  answer:2, explain:"Decades of Smokey Bear messaging taught that all fire is bad." },
{ id:"cc-18", ch:"cons", src:"Conservation quiz Q18", type:"mc",
  q:"One possible solution to the problem of insufficient land area for preserves is to use ____________ to link smaller habitat areas.",
  options:["Highways","Eco-bridges","Edge effects","Corridors","None of these is correct"],
  answer:3, explain:"Corridors let species move between patches." },
{ id:"cc-19", ch:"cons", src:"Conservation quiz Q19", type:"mc",
  figure:"Four preserve shapes: a = long rectangle, b = thin crescent, c = circle, d = irregular hourglass.",
  q:"Which of the preserve shapes shown has the greatest interior area relative to perimeter area?",
  options:["A (long rectangle)","B (thin crescent)","C (circle)","D (irregular hourglass)","All of the shapes have about the same interior/perimeter measurements"],
  answer:2, explain:"The circle maximizes interior and minimizes edge." },
{ id:"cc-20", ch:"cons", src:"Conservation quiz Q20", type:"mc",
  q:"Accounting for over half of all deforestation in tropical regions is ________.",
  options:["the highly productive nature of tropical soils","the need for agricultural expansion","the harvesting of natural forest products for food","the unlimited supply of land","the need for urban development"],
  answer:1, explain:"Farms and pasture are the main drivers." },
{ id:"cc-21", ch:"cons", src:"Conservation quiz Q21", type:"mc",
  q:"What are the most endangered aquatic areas?",
  options:["Coral reefs","Tide pools","Mangrove forests","Sea mounts"],
  answer:0, explain:"Warming, bleaching, sediment, and overfishing threaten reefs worldwide." },
{ id:"cc-22", ch:"cons", src:"Conservation quiz Q22", type:"mc",
  q:"Edge effects are the result of which of the following?",
  options:["Populations of flora and fauna have emigrated from the core of their population center to the edge of their habitat.","Metapopulations of some of the larger fauna have become more dominant on the landscape and as a result have increased the edge of their habitat.","Habitat fragmentation or habitat shrinkage has occurred, and thus the edge of the habitat has increased in relative proportion.","Habitat fragmentation or habitat shrinkage has occurred, and thus the edge of the habitat has decreased in relative proportion.","Populations of particular species have decreased and are on the edge of extinction."],
  answer:2, explain:"Smaller pieces have more edge per unit of interior." },
{ id:"cc-23", ch:"cons", src:"Conservation quiz Q23", type:"mc",
  q:"A heterogeneous area consisting of a patchwork of distinctive ecosystems is called a ___________.",
  options:["habitat","matrix","landscape","geographic unit","community"],
  answer:2, explain:"Landscape ecology studies this patchwork." },
{ id:"cc-24", ch:"cons", src:"Conservation quiz Q24", type:"mc",
  q:"How can viable genetic diversity be restored when a population becomes very small?",
  options:["Through hybridization with another species","Through inbreeding","Through asexual reproduction","Through sterile breeding techniques","Through captive breeding programs"],
  answer:4, explain:"Managed captive breeding maximizes the diversity that remains." },
{ id:"cc-25", ch:"cons", src:"Conservation quiz Q25", type:"mc",
  q:"Extinction rates on islands are predicted, based on island biogeography, to be lowest",
  options:["On small islands","On large islands","On near islands","On far islands","On small islands near far islands"],
  answer:1, explain:"Size controls extinction; distance controls immigration." },
{ id:"cc-26", ch:"cons", src:"Conservation quiz Q26", type:"mc", missed:true, you:1,
  figure:"Bar graph of wood use by continent (fuelwood vs lumber vs paper fiber).",
  q:"Which of the following continents is using the majority of harvested wood for lumber or solid wood products?",
  options:["South America","North America","Europe","Asia","Africa"],
  answer:2, explain:"You answered North America. In the graph, Europe devotes the largest share of its harvest to lumber and solid wood (and the least to fuel). North America splits between lumber and paper." },
{ id:"cc-27", ch:"cons", src:"Conservation quiz Q27", type:"tf",
  q:"Some areas such as mountain tops, or even individual trees, may act as habitat islands.",
  options:["True","False"], answer:0,
  explain:"Island biogeography applies to any isolated patch of habitat." },
{ id:"cc-28", ch:"cons", src:"Conservation quiz Q28", type:"mc",
  q:"Complete removal of the forest canopy is ________.",
  options:["even-aged management","uneven aged management","selective harvesting","clear cutting","fire management"],
  answer:0, explain:"The quiz key is even-aged management (the system that uses clear-cutting so regrowth is all one age)." },
{ id:"cc-29", ch:"cons", src:"Conservation quiz Q29", type:"tf",
  q:"The passenger pigeon went extinct due to natural causes.",
  options:["True","False"], answer:1,
  explain:"Market hunting and habitat loss drove billions of birds to extinction by 1914." },
{ id:"cc-30", ch:"cons", src:"Conservation quiz Q30", type:"mc", missed:true, you:1,
  figure:"Bar graph of wood use by continent (fuelwood vs lumber vs paper fiber).",
  q:"Which of the following continents is using the majority of wood for fiber to produce paper?",
  options:["South America","North America","Europe","Asia","Africa"],
  answer:0, explain:"You answered North America. In the graph South America sends the largest share of its harvest to pulp and paper (eucalyptus and pine plantations in Brazil and Chile)." },
{ id:"cc-31", ch:"cons", src:"Conservation quiz Q31", type:"mc",
  q:"Which of the following is not a role played by biodiversity within an ecosystem?",
  options:["biogeochemical cycling","waste recycling","water purification","prevention of soil erosion","All of the choices are roles played by biodiversity."],
  answer:4, explain:"All are ecosystem services." },
{ id:"cc-32", ch:"cons", src:"Conservation quiz Q32", type:"mc",
  q:"Over the past decade, the number of park visitors has _______ and park budgets have ________.",
  options:["increased by more than one half; increased by about 25%","increased by one third; decreased by about 25%","decreased by more than one half; decreased by about 25%","decreased by one third; increased by about 25%","stayed about the same; decreased by about 25%"],
  answer:1, explain:"More visitors, less money: an extrinsic problem for parks." },
{ id:"cc-33", ch:"cons", src:"Conservation quiz Q33", type:"mc",
  q:"Breaking up a continuous habitat into smaller fragments will have which of the following effects?",
  options:["it will increase the number of available habitats","it will decrease the total amount of edge in the habitat","it will increase the total amount of edge in the habitat","it will have no effect"],
  answer:2, explain:"Fragmentation multiplies edges." },
{ id:"cc-34", ch:"cons", src:"Conservation quiz Q34", type:"mc",
  q:"Although most of the world's forests are shrinking, biologists are especially concerned about tropical forest loss because",
  options:["They contain such high biodiversity","Tropical trees are the biggest trees in the world","They contain irreplaceable wood resources","There are fewer remaining tropical forests than any other forest type","All of these are reasons that biologists are especially concerned about tropical forest loss"],
  answer:0, explain:"Over half of all species live in tropical forests." },
{ id:"cc-35", ch:"cons", src:"Conservation quiz Q35", type:"mc",
  q:"On a global scale, fuelwood harvests",
  options:["Make up about half of all wood harvests","Make up only 1% of industrial timber harvests","Are far greater than industrial timber harvests","Make up about 10% of all wood harvests","Are mainly in developed countries"],
  answer:0, explain:"Roughly half of harvested wood is burned, mostly in developing countries." },
{ id:"cc-36", ch:"cons", src:"Conservation quiz Q36", type:"mc",
  q:"An increased number of cowbirds (a species that likes areas where grassland and forests meet) would be an indicator of",
  options:["overharvest of timber.","overgrazing of grasslands.","increased edge habitat.","decreased biodiversity.","lack of proper habitat management."],
  answer:2, explain:"Cowbirds are an edge species and brood parasite." },
{ id:"cc-37", ch:"cons", src:"Conservation quiz Q37", type:"mc",
  q:"In the Florida Everglades, what is now being done to restore wetland habitat?",
  options:["Removal of man-made channels to allow water to shed over the land.","Removal of grazing livestock that had overconsumed vegetation and dried the landscape.","The conversion of cane sugar farms into wetland by using eminent domain.","The persistent removal of invasive species like snakes and rats to allow natural recovery of native wildlife."],
  answer:0, explain:"Restoring sheet flow is the core of Everglades restoration." },
{ id:"cc-38", ch:"cons", src:"Conservation quiz Q38", type:"mc",
  q:"What role do fast food chains serve in the loss of habitat?",
  options:["Land is cleared for grazing cattle to sustain the growing beef industry.","Land is cleared for demand for grains to sustain the demand for bread.","Fast food chains spur urban growth that consume open spaces.","They actively discourage ranchers to place lands under conservation easements."],
  answer:0, explain:"Beef demand drives tropical forest clearing for pasture." },
{ id:"cc-39", ch:"cons", src:"Conservation quiz Q39", type:"mc",
  q:"How does a bioreserve differ from traditional conservation lands?",
  options:["They lack publicly preserved lands.","They do not allow any human activity within the reserve.","They include a blend of human occupancy with areas where human activity is off-limits.","They are owned by a consortium of non-profits rather than government agencies."],
  answer:2, explain:"Core, buffer, and transition zones." },
{ id:"cc-40", ch:"cons", src:"Conservation quiz Q40", type:"mc",
  q:"Which of the following has NOT elevated the risk of wildfires?",
  options:["Growth in residential home building in wildfire prone habitats.","Prescribed burns to manage secondary/understory growth in young forest.","Decades long active fire suppression of fire adapted landscapes.","Land clearing for subsistence farming in poor nations.","Clear cutting followed by dense successional regrowth of forest."],
  answer:1, explain:"Prescribed burns reduce fuel and therefore reduce risk." },
{ id:"cc-41", ch:"cons", src:"Conservation quiz Q41", type:"mc",
  q:"Which of the following is NOT a significant threat to songbirds in North America?",
  options:["brood parasitism by brown headed cowbirds","increased nest predation along forest edges","Feral and free roaming domestic cats","Towers and window rich high rises.","none of the above"],
  answer:4, explain:"All four are major threats." },
{ id:"cc-42", ch:"cons", src:"Conservation quiz Q42 (answer cut off in PDF)", type:"mc", missed:true, you:-1,
  q:"Of the remaining old growth forest on earth, what human activity is an ever-present threat?",
  options:["Urban sprawl","Conservation easements","Logging / timber harvesting","Ecotourism"],
  answer:2, explain:"You lost credit on this one but the PDF cut off the remaining options and your answer. Conservation easements protect land and sprawl rarely reaches remote old growth; logging for timber is the constant threat to old-growth forest. The options shown here beyond A and B are reconstructed." }
];
